import{_ as e,o as t,c as a,a2 as d}from"./chunks/framework.DHtetOlu.js";const p=JSON.parse('{"title":"Console","description":"","frontmatter":{},"headers":[],"relativePath":"scripting/console.md","filePath":"scripting/console.md"}'),r={name:"scripting/console.md"};function c(s,o,i,n,l,u){return t(),a("div",null,[...o[0]||(o[0]=[d('<h1 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h1><p>Tudo o que você faz na interface aparece no <strong>console</strong> (embaixo do canvas) como o comando equivalente. O contrário também vale: digitar um comando faz a ação, e o desenho acompanha. É a mesma linguagem usada pelos scripts da <a href="./bridge.html">ponte local</a> e pelo script exportado.</p><h2 id="a-linguagem" tabindex="-1">A linguagem <a class="header-anchor" href="#a-linguagem" aria-label="Permalink to &quot;A linguagem&quot;">​</a></h2><p>Uma linguagem com cara de Python:</p><ul><li>números, strings (<code>&quot;...&quot;</code> ou <code>&#39;...&#39;</code>), tuplas <code>(x, y)</code>, listas <code>[a, b]</code>, <code>True</code>, <code>False</code> e <code>None</code>;</li><li>argumentos nomeados: <code>g.circle((0, 0), r=5)</code>;</li><li>variáveis do console: <code>a = g.point((0, 0))</code> guarda o id do ponto criado para usar depois;</li><li>comentários com <code>#</code>.</li></ul><p>Comprimentos são números na unidade do projeto ou strings com unidade (<code>&quot;5 mm&quot;</code>, <code>&quot;0.2 in&quot;</code>). Coordenadas de pontos, como <code>(x, y)</code>, são em mm. Ângulos são strings com unidade (<code>&quot;30 deg&quot;</code>).</p><h2 id="objetos" tabindex="-1">Objetos <a class="header-anchor" href="#objetos" aria-label="Permalink to &quot;Objetos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Objeto</th><th>Etapa</th><th>Exemplos</th></tr></thead><tbody><tr><td><code>g</code></td><td>Geometria</td><td><code>g.line((0, 0), (40, 0))</code>, <code>g.distance(&quot;l1&quot;, &quot;40 mm&quot;)</code>, <code>g.var(&quot;g&quot;, &quot;0.5 mm&quot;)</code></td></tr><tr><td><code>m</code></td><td>Malha</td><td><code>m.region((5, 5), material=&quot;mat_cu&quot;)</code>, <code>m.circuit(&quot;Bobina&quot;, current=&quot;10&quot;)</code>, <code>m.generate()</code></td></tr><tr><td><code>s</code></td><td>Método de resolução</td><td><code>s.physics(&quot;n2&quot;, analysis=&quot;transient&quot;, dt=&quot;0.001&quot;, t_end=&quot;0.05&quot;)</code>, <code>s.solve()</code></td></tr><tr><td><code>r</code></td><td>Resultados</td><td><code>r.view(&quot;n2&quot;)</code>, <code>r.table(&quot;n2&quot;)</code>, <code>r.result(&quot;Bobina_L&quot;)</code></td></tr><tr><td><code>c</code></td><td>Esquemático</td><td><code>c.part(&quot;n5&quot;, &quot;R&quot;, value=&quot;0.5&quot;)</code>, <code>c.wire(...)</code></td></tr></tbody></table><p>Sem objeto, o comando vale como geometria: <code>line((0, 0), (10, 0))</code> é o mesmo que <code>g.line(...)</code>.</p><h2 id="funcoes-globais" tabindex="-1">Funções globais <a class="header-anchor" href="#funcoes-globais" aria-label="Permalink to &quot;Funções globais&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Função</th><th>Faz</th></tr></thead><tbody><tr><td><code>help()</code></td><td>lista os comandos</td></tr><tr><td><code>getid(&quot;nome&quot;)</code></td><td>id de uma entidade, região ou nó pelo nome</td></tr><tr><td><code>undo()</code>, <code>redo()</code></td><td>desfaz e refaz</td></tr><tr><td><code>fit()</code></td><td>ajusta a vista</td></tr><tr><td><code>reset()</code></td><td>começa um projeto vazio, com as bibliotecas padrão (para scripts; o arquivo aberto não muda)</td></tr></tbody></table><h2 id="recursos-do-console" tabindex="-1">Recursos do console <a class="header-anchor" href="#recursos-do-console" aria-label="Permalink to &quot;Recursos do console&quot;">​</a></h2><ul><li><strong>Tab</strong> completa comandos, ids, nomes e variáveis; dentro de aspas, sugere ids e nomes do desenho.</li><li><strong>↑</strong> e <strong>↓</strong> percorrem o histórico.</li><li>O botão de copiar copia o histórico como script; itens desfeitos aparecem em cinza.</li><li>Erros mostram uma mensagem legível, sem mudar o modelo.</li></ul><h2 id="script-exportado" tabindex="-1">Script exportado <a class="header-anchor" href="#script-exportado" aria-label="Permalink to &quot;Script exportado&quot;">​</a></h2><p>O botão <code>&lt;/&gt;</code> ao lado de <strong>Modelo</strong> gera um script que começa com <code>clear()</code> e recria o projeto inteiro com os mesmos ids: entidades, restrições, grupos, variáveis, materiais, regiões, contornos, malha, físicas e resultados. Um teste automático garante a ida e volta (o modelo recriado é idêntico). Dá para colar esse script no console ou enviá-lo por um script externo, por exemplo para varrer parâmetros.</p><p>Veja a <a href="./api.html">referência completa da API</a>.</p>',16)])])}const q=e(r,[["render",c]]);export{p as __pageData,q as default};
